<?php
/** Proof — pulling the kernel's months (spec "Proof", 1): the two months pulled, the open one not importable; a document kept verbatim; the kernel down → 502 in words; a bad token → the sentence. */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
$sept = sept_doc(); $oct = oct_doc();
ledger_state(['2026-10' => $oct, '2026-09' => $sept]);
echo "1. The page before any pull\n";
$body = page($bea, '/ap/ai/')['body'];
ok(str_contains($body, 'id="ai-statement-card-202610-notpulled"') && str_contains($body, 'id="ai-statement-card-202609-notpulled"') && str_contains($body, 'open in the OS') && str_contains($body, 'the ledger has not pulled it yet') && str_contains($body, 'id="ai-statements-pull-btn"'), 'months the OS lists but the ledger has not pulled are muted cards with their own Pull; the page has Pull now');
$d = screen($bea, '/ap/ai/')[1];
ok(count($d['statements'] ?? []) === 2 && $d['statements'][0]['period'] === '2026-10' && $d['statements'][0]['pulled'] === false && $d['statements'][1]['kernel_status'] === 'closed' && array_key_exists('kernel_error', $d) && $d['kernel_error'] === null, 'JSON: both months, newest first, not pulled; no kernel error');
$body = page($vera, '/ap/ai/')['body'];
ok(!str_contains($body, 'id="ai-statements-pull-btn"') && str_contains($body, 'id="ai-statement-card-202609-notpulled"') && !str_contains($body, 'ai-statement-card-202609-notpulled-pull-btn'), 'a Viewer reads the page without Pull');
echo "2. Pull every month\n";
[$c, $b] = act($vera, '/ap/ai/pull.php', []);
ok($c === 403, 'a Viewer pulling: 403');
$since = last_activity_id();
[$c, $b] = act($bea, '/ap/ai/pull.php', []);
ok($c === 200 && count($b['pulled'] ?? []) === 2 && ($b['refused'] ?? [1]) === [] && ($b['location'] ?? '') === '/ap/ai/?notice=pulled', 'ai_statement_pull (every month): 200, two months pulled');
$oc = q("SELECT * FROM ai_statements WHERE period = '2026-10'")[0]; $se = q("SELECT * FROM ai_statements WHERE period = '2026-09'")[0];
ok($oc['kernel_status'] === 'open' && $oc['status'] === 'pulled' && $se['kernel_status'] === 'closed' && $se['status'] === 'pulled' && $se['period_start'] === '2026-09-01' && $se['period_end'] === '2026-09-30' && (int) $se['late_calls'] === 2, 'October open, September closed, both "pulled"; September has 2 late calls');
ok((int) one('SELECT count(*) FROM ai_statement_lines WHERE statement_id = :s', ['s' => $se['id']]) === 4 && (int) one('SELECT count(*) FROM ai_statement_lines WHERE statement_id = :s', ['s' => $oc['id']]) === 1, 'the lines are kept verbatim: four and one');
$ln = q('SELECT * FROM ai_statement_lines WHERE statement_id = :s ORDER BY line_no', ['s' => $se['id']]);
ok($ln[0]['amount'] === '12.3456' && $ln[1]['note'] === '2 late calls' && (int) $ln[1]['late_calls'] === 2 && (int) $ln[0]['department_id'] === 3 && (int) $ln[1]['department_id'] === 5 && (int) $ln[3]['department_id'] === 6 && $ln[0]['agent'] === 'Sasha' && $ln[2]['model'] === 'claude-opus-5-5', 'amounts to four decimals, the note, the late calls, the agent and model; departments resolved by name (Accounting 3, IT 5, Front Office 6)');
ok(json_decode($se['document'], true) == json_decode(json_encode($sept), true) && $se['document_hash'] === hash('sha256', (string) one('SELECT document::text FROM ai_statements WHERE id = :s', ['s' => $se['id']])), 'the document is kept as sent (jsonb) with its sha256');
$l = activity('ai_statement.pull', $since); $a0 = json_decode((string) $l[0]['after'], true);
ok(count($l) === 2 && array_unique(array_column($a0 ? [$a0] : [], 'changed')) === ['new'] && in_array($a0['period'], ['2026-09', '2026-10'], true) && isset($a0['kernel_status']), 'ai_statement.pull logged once per month with period, kernel_status and changed = new');
[$c, $b] = act($bea, '/ap/ai/pull.php', []);
ok($c === 200 && array_unique(array_column($b['pulled'], 'changed')) === ['unchanged'], 'pulling again: every month is "unchanged"');
$body = page($bea, '/ap/ai/')['body'];
ok(str_contains($body, 'id="ai-statement-card-' . $se['id'] . '"') && str_contains($body, 'id="ai-statement-card-' . $se['id'] . '-kernel">closed') && str_contains($body, 'id="ai-statement-card-' . $oc['id'] . '-kernel">open in the OS') && str_contains($body, '23.01 USD') && str_contains($body, '2 late calls') && str_contains($body, 'id="ai-statement-card-' . $se['id'] . '-status">pulled'), 'the cards: closed / open in the OS, the total (23.01 USD), late calls, the ledger\'s state "pulled"');
ok(!str_contains($body, 'notpulled'), 'and no muted card once both are pulled');
echo "3. One month, and the open month\n";
[$c, $b] = act($bea, '/ap/ai/pull.php', ['period' => '2026-09']);
ok($c === 200 && count($b['pulled']) === 1 && $b['pulled'][0]['period'] === '2026-09', 'a single month by period');
[$c, $b] = act($bea, '/ap/ai/pull.php', ['period' => '2026-9']);
ok($c === 422 && isset(fields($b)['period']), 'a malformed period: 422 naming the field');
[$c, $b] = act($bea, '/ap/ai/pull.php', ['period' => '2025-01']);
ok($c === 422 && str_contains(msg($b), 'The OS refused'), 'a month the OS has no document for: 422 in the OS\'s words (' . msg($b) . ')');
[$c, $b] = act($bea, '/ap/ai/import.php', ['ai_statement' => stmt_id('2026-10')]);
ok($c === 422 && str_contains(msg($b), 'Statement 2026-10 is still open in the OS; only a closed month becomes bills'), 'the open month is not importable: 422 "Statement 2026-10 is still open in the OS; only a closed month becomes bills"');
$d = screen($bea, '/ap/ai/' . stmt_id('2026-10'))[1];
ok(($d['may']['import'] ?? true) === false && ($d['statement']['kernel_status'] ?? '') === 'open', 'and the page offers no Import for it');
$body = page($bea, '/ap/ai/' . stmt_id('2026-10'))['body'];
ok(str_contains($body, 'id="ai-statement-import-why"') && !str_contains($body, 'id="ai-statement-import-btn"') && str_contains($body, 'Still open in the OS'), 'the open month says why');
echo "4. A month that changes before it is imported\n";
$sept2 = sept_doc(); $sept2['lines'][3]['amount'] = '3.5000'; $sept2 = ai_doc('2026-09', 'closed', $sept2['lines']);
ledger_state(['2026-10' => $oct, '2026-09' => $sept2]);
[$c, $b] = act($bea, '/ap/ai/pull.php', ['period' => '2026-09']);
ok($c === 200 && $b['pulled'][0]['changed'] === 'updated' && (string) one("SELECT amount FROM ai_statement_lines WHERE statement_id = :s AND provider = 'openai'", ['s' => stmt_id('2026-09')]) === '3.5000', 'a different document for a month not yet imported is taken ("updated")');
ledger_state(['2026-10' => $oct, '2026-09' => $sept]);
act($bea, '/ap/ai/pull.php', ['period' => '2026-09']);
ok((string) one("SELECT amount FROM ai_statement_lines WHERE statement_id = :s AND provider = 'openai'", ['s' => stmt_id('2026-09')]) === '3.0000', 'and taken back');
$now = ai_doc('2026-10', 'closed', $oct['lines']);
ledger_state(['2026-10' => $now, '2026-09' => $sept]);
[$c, $b] = act($bea, '/ap/ai/pull.php', ['period' => '2026-10']);
ok($c === 200 && $b['pulled'][0]['changed'] === 'updated' && (string) one("SELECT kernel_status FROM ai_statements WHERE period = '2026-10'") === 'closed', 'a month the OS closes since is updated to closed — and then importable');
ledger_state(['2026-10' => $oct, '2026-09' => $sept]);
act($bea, '/ap/ai/pull.php', ['period' => '2026-10']);
echo "5. The kernel down, and a bad token\n";
ledger_state(['2026-10' => $oct, '2026-09' => $sept], 'down');
[$c, $b] = act($bea, '/ap/ai/pull.php', []);
ok($c === 502 && str_contains(msg($b), 'The OS did not answer: it replied HTTP 503 with something that is not JSON.'), 'the OS down: 502 "The OS did not answer: it replied HTTP 503 with something that is not JSON."');
$r = req('GET', '/ap/ai/', ['jar' => $bea]);
ok($r['code'] === 200 && str_contains($r['body'], 'id="ai-statements-kernel-error"') && str_contains($r['body'], 'The OS did not answer') && str_contains($r['body'], 'what the ledger already holds') && str_contains($r['body'], 'id="ai-statement-card-' . stmt_id('2026-09') . '"'), 'the page still opens: it says the OS did not answer and shows what the ledger holds');
$d = screen($bea, '/ap/ai/')[1];
ok(str_contains((string) ($d['kernel_error'] ?? ''), 'The OS did not answer') && count($d['statements']) === 2, 'JSON: kernel_error carries the sentence; the pulled months are still listed');
ledger_state(['2026-10' => $oct, '2026-09' => $sept], 'unauthorized');
[$c, $b] = act($bea, '/ap/ai/pull.php', ['period' => '2026-09']);
ok($c === 502 && msg($b) === 'The application token is not accepted by the OS.', 'a token the OS refuses: "The application token is not accepted by the OS."');
ledger_state(['2026-10' => $oct, '2026-09' => $sept]);
$bad = trim((string) shell_exec('OS_INTERNAL_URL=http://127.0.0.1:9 php ' . escapeshellarg(dirname(__DIR__, 3) . '/bin/ai_poll.php') . ' 2>&1'));
ok(str_contains($bad, 'The OS did not answer: it could not be reached'), 'an OS that cannot be reached at all (a closed port): the poll says "The OS did not answer: it could not be reached …" (' . substr($bad, 0, 80) . ')');
[$c, $b] = act($bea, '/ap/ai/pull.php', ['period' => '2026-09']);
ok($c === 200, 'the OS back: pulling works again');
finish();
